head.script:
scwin.init = function() {
    alert(scwin.$w.getRuntimeId("trigger1"));
    scwin.increaseCount();
}
scwin.trigger1_onclick = function(e) {
    $w.url("/sample/common_link/etc_reload_callback_SKT-576_(WSQ-1156)_sub1.xml", {
        "spa": true
    });
};
scwin.increaseCount = function() {
    if (!localStorage.getItem("count")) {
        localStorage.setItem("count", 0);
    }
    var count = parseInt(localStorage.getItem("count"));
    count = count + 1;
    localStorage.setItem("count", count);
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
}
